## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/biliaryStricturesLogic.ts`

```typescript
/**
 * Biliary Strictures & Malignancy Workup Clinical Logic Engine
 * Based on: ASGE Guideline on Biliary Strictures (2019, 2024 Update)
 *           ESGE Guideline on Biliary Strictures (2022)
 *           ACG Clinical Guideline: Primary Sclerosing Cholangitis (2023)
 *           NCCN Guidelines: Biliary Tract Cancers (2025)
 *           ASGE Guideline on Cholangioscopy (2018, 2024 Update)
 * Key decisions: Benign vs malignant differentiation, tissue acquisition strategy,
 *                ERCP vs EUS sequencing, PSC management, hilar vs distal classification
 */

export type StrictureLocation =
  | 'distal_cbd' // Below cystic duct — most common
  | 'hilar_bismuth_I' // Common hepatic duct
  | 'hilar_bismuth_II' // Bifurcation
  | 'hilar_bismuth_III' // Unilateral hepatic duct
  | 'hilar_bismuth_IV' // Bilateral hepatic ducts
  | 'intrahepatic'
  | 'cystic_duct'
  | 'anastomotic'; // Post-liver transplant

export type StrictureEtiology =
  | 'unknown_malignant_suspected'
  | 'cholangiocarcinoma_suspected'
  | 'pancreatic_cancer'
  | 'gallbladder_cancer'
  | 'ampullary_cancer'
  | 'metastatic_disease'
  | 'psc' // Primary sclerosing cholangitis
  | 'igg4_cholangiopathy' // IgG4-related sclerosing cholangitis
  | 'post_surgical' // Post-cholecystectomy, post-transplant
  | 'chronic_pancreatitis'
  | 'choledocholithiasis_related'
  | 'radiation_induced'
  | 'benign_idiopathic';

export type TissueAcquisitionResult =
  | 'not_performed'
  | 'malignant'
  | 'high_grade_dysplasia'
  | 'suspicious'
  | 'atypical'
  | 'benign'
  | 'non_diagnostic'
  | 'pending';

export interface BiliaryStrictureInput {
  // Stricture characteristics
  strictureLocation: StrictureLocation;
  suspectedEtiology: StrictureEtiology;
  strictureLengthCm?: number;
  hasProximalDilation: boolean;
  proximalDuctDiameterMm?: number;

  // Clinical presentation
  hasJaundice: boolean;
  bilirubinMgDl?: number;
  hasAbdominalPain: boolean;
  hasWeightLoss: boolean;
  hasFever: boolean; // Suggests cholangitis
  hasChills: boolean;
  hasPruritus: boolean;

  // Tumor markers
  ca199?: number;
  cea?: number;
  ca125?: number;
  igg4?: number; // >135 mg/dL = IgG4-related cholangiopathy

  // Imaging
  hasCTScan: boolean;
  hasMRCP: boolean;
  hasERCP: boolean;
  hasEUSPerformed: boolean;
  hasPETScan: boolean;
  imagingFindingsMalignantFeatures: boolean; // Mass, vascular involvement, LN

  // Tissue acquisition
  tissueAcquisitionResult: TissueAcquisitionResult;
  tissueMethod?: 'ercp_brush_cytology' | 'ercp_forceps_biopsy' | 'eus_fnb' | 'cholangioscopy_biopsy' | 'percutaneous';
  numberOfPriorBiopsyAttempts?: number;

  // PSC specific
  hasPSC: boolean;
  pscDiagnosisYear?: number;
  pscType?: 'large_duct' | 'small_duct';
  hasIBDWithPSC: boolean;
  hasDominantStricture: boolean; // PSC dominant stricture — malignancy risk
  hasCholangiocarcInPSC: boolean;

  // Biliary drainage
  hasBiliaryStenosis: boolean;
  hasBiliaryStent: boolean;
  stentType?: 'plastic' | 'sems_covered' | 'sems_uncovered';
  stentPlacementYear?: number;
  hasStentOcclusion: boolean;

  // Resectability
  isResectable: boolean;
  hasVascularInvolvement: boolean;
  hasLymphadenopathy: boolean;
  hasDistantMetastases: boolean;
  hasLiverMetastases: boolean;

  // Patient factors
  ageYears: number;
  isSurgicalCandidate: boolean;
  performanceStatus: 'good' | 'moderate' | 'poor';
  hasCoagulopathy: boolean;
  inrValue?: number;
  isOnAnticoagulation: boolean;
}

export interface BiliaryStrictureRecommendation {
  primaryRecommendation: string;
  malignancyRiskAssessment: string;
  diagnosticWorkup: string;
  tissueAcquisitionStrategy: string;
  biliarDrainageStrategy: string;
  pscManagement: string;
  resectabilityAndOncology: string;
  surveillancePlan: string;
  urgentFlags: string[];
  nextSteps: string[];
  evidenceLevel: 'A' | 'B' | 'C';
  rationale: string;
  references: Array<{ citation: string; pmid?: string; url?: string }>;
}

export function assessBiliaryStricture(input: BiliaryStrictureInput): BiliaryStrictureRecommendation {
  const urgentFlags: string[] = [];
  const nextSteps: string[] = [];

  // ─── Urgent Flags ─────────────────────────────────────────────────────────
  if (input.hasFever && input.hasChills && input.hasJaundice) {
    urgentFlags.push('ACUTE CHOLANGITIS (Charcot\'s triad): urgent biliary decompression required — ERCP within 24–48h. IV antibiotics (piperacillin-tazobactam or ceftriaxone + metronidazole).');
  }
  if (input.bilirubinMgDl !== undefined && input.bilirubinMgDl > 15) {
    urgentFlags.push(`Severe jaundice (bilirubin ${input.bilirubinMgDl} mg/dL): biliary drainage required before any systemic therapy — ERCP or EUS-BD`);
  }
  if (input.hasStentOcclusion) {
    urgentFlags.push('Biliary stent occlusion: ERCP for stent exchange — risk of cholangitis. Upgrade to SEMS if recurrent occlusion.');
  }
  if (input.hasPSC && input.hasDominantStricture) {
    urgentFlags.push('PSC with dominant stricture: high risk of cholangiocarcinoma — ERCP with brush cytology + FISH, cholangioscopy with biopsy, and CA 19-9 + IgG4 measurement');
  }
  if (input.igg4 !== undefined && input.igg4 > 135) {
    urgentFlags.push(`IgG4 ${input.igg4} mg/dL (>135): IgG4-related sclerosing cholangitis — steroid trial (prednisone 40mg/day x4 weeks) before biliary stenting if clinically stable`);
  }

  // ─── Malignancy Risk Assessment ───────────────────────────────────────────
  let malignancyRiskScore = 0;
  const malignancyFeatures: string[] = [];

  if (input.imagingFindingsMalignantFeatures) { malignancyRiskScore += 2; malignancyFeatures.push('Malignant imaging features (mass, vascular involvement)'); }
  if (input.ca199 !== undefined && input.ca199 > 100) { malignancyRiskScore += 2; malignancyFeatures.push(`CA 19-9 ${input.ca199} U/mL (>100)`); }
  if (input.hasWeightLoss) { malignancyRiskScore += 1; malignancyFeatures.push('Weight loss'); }
  if (input.hasLymphadenopathy) { malignancyRiskScore += 1; malignancyFeatures.push('Lymphadenopathy'); }
  if (input.hasPSC) { malignancyRiskScore += 1; malignancyFeatures.push('PSC (13x higher CCA risk)'); }
  if (input.strictureLengthCm !== undefined && input.strictureLengthCm > 2) { malignancyRiskScore += 1; malignancyFeatures.push(`Long stricture (${input.strictureLengthCm}cm)`); }
  if (input.ageYears > 60) { malignancyRiskScore += 1; malignancyFeatures.push('Age >60'); }

  const malignancyRisk = malignancyRiskScore >= 4 ? 'HIGH' : malignancyRiskScore >= 2 ? 'INTERMEDIATE' : 'LOW';

  const malignancyRiskAssessment =
    `MALIGNANCY RISK: ${malignancyRisk} (score ${malignancyRiskScore}/9). ` +
    (malignancyFeatures.length > 0 ? `Risk features: ${malignancyFeatures.join(', ')}. ` : '') +
    (input.igg4 !== undefined && input.igg4 > 135
      ? 'IgG4 elevated — consider IgG4-related cholangiopathy (benign) before assuming malignancy. '
      : '') +
    'Benign causes to exclude: PSC, IgG4-related cholangiopathy, post-surgical stricture, chronic pancreatitis, Mirizzi syndrome.';

  // ─── Diagnostic Workup ────────────────────────────────────────────────────
  let diagnosticWorkup = '';
  if (!input.hasCTScan && !input.hasMRCP) {
    diagnosticWorkup =
      'IMAGING REQUIRED (ASGE 2024): ' +
      '1) MRCP (preferred for biliary strictures): best for stricture characterization, extent, and duct anatomy. ' +
      '2) CT abdomen/pelvis (triple-phase): vascular involvement, lymphadenopathy, metastases. ' +
      '3) Both CT and MRCP are complementary — perform both for suspected malignant stricture.';
    nextSteps.push('MRCP for biliary stricture characterization', 'CT abdomen/pelvis (triple-phase) for staging');
  } else if (!input.hasMRCP) {
    diagnosticWorkup = 'MRCP recommended — superior to CT for biliary anatomy and stricture characterization.';
    nextSteps.push('MRCP for biliary anatomy');
  } else {
    diagnosticWorkup = 'Cross-sectional imaging performed. Proceed with tissue acquisition strategy.';
  }

  // ─── Tissue Acquisition Strategy ─────────────────────────────────────────
  let tissueAcquisitionStrategy = '';
  if (input.tissueAcquisitionResult === 'not_performed' || input.tissueAcquisitionResult === 'non_diagnostic') {
    if (input.strictureLocation === 'distal_cbd' || input.strictureLocation === 'hilar_bismuth_I') {
      tissueAcquisitionStrategy =
        'TISSUE ACQUISITION for biliary stricture (ASGE 2024 — sequential strategy): ' +
        '1) ERCP BRUSH CYTOLOGY: sensitivity 30–40% (low), specificity 99%. ' +
        '   Inadequate alone — always combine with additional techniques. ' +
        '2) ERCP FORCEPS BIOPSY: sensitivity 40–50%. Combine with cytology. ' +
        '3) FLUORESCENCE IN SITU HYBRIDIZATION (FISH): improves sensitivity to 50–60% when added to cytology. ' +
        '4) CHOLANGIOSCOPY (SpyGlass DS) with TARGETED BIOPSY: ' +
        '   PREFERRED for indeterminate strictures (ASGE 2024 Strong Recommendation). ' +
        '   Direct visualization of stricture + targeted forceps biopsy. ' +
        '   Sensitivity: 60–80% for malignancy. Specificity: 95–98%. ' +
        '   SpyBite Max forceps: larger biopsy samples — improved yield. ' +
        '5) EUS-FNB: preferred for distal CBD strictures with periductal mass. ' +
        '   Avoid if resectable — theoretical seeding risk (controversial). ' +
        '6) NEXT-GENERATION SEQUENCING (NGS) on bile/brush cytology: emerging — improves diagnostic yield.';
      if (input.numberOfPriorBiopsyAttempts !== undefined && input.numberOfPriorBiopsyAttempts >= 1) {
        nextSteps.push('Cholangioscopy (SpyGlass DS) with targeted biopsy — preferred for indeterminate stricture after failed ERCP cytology');
      } else {
        nextSteps.push('ERCP with brush cytology + forceps biopsy + FISH', 'Cholangioscopy if ERCP cytology non-diagnostic');
      }
    } else if (input.strictureLocation.startsWith('hilar')) {
      tissueAcquisitionStrategy =
        'TISSUE ACQUISITION for HILAR STRICTURE (ASGE 2024): ' +
        '1) ERCP brush cytology + FISH: first-line. ' +
        '2) Cholangioscopy (SpyGlass DS): preferred for hilar strictures — allows direct visualization of both hepatic ducts. ' +
        '   Bilateral cholangioscopy for Bismuth III–IV. ' +
        '3) EUS-FNB: limited access to hilar strictures — use for accessible periductal lymph nodes. ' +
        '4) Percutaneous transhepatic cholangioscopy (PTCS): if ERCP access not feasible.';
      nextSteps.push('ERCP with brush cytology + FISH for hilar stricture', 'Cholangioscopy if cytology non-diagnostic');
    }
  } else if (input.tissueAcquisitionResult === 'malignant' || input.tissueAcquisitionResult === 'high_grade_dysplasia') {
    tissueAcquisitionStrategy = `Tissue acquisition confirmed: ${input.tissueAcquisitionResult.replace(/_/g, ' ')}. Proceed with oncologic staging and multidisciplinary planning.`;
  } else if (input.tissueAcquisitionResult === 'benign') {
    tissueAcquisitionStrategy =
      'Benign tissue result: does NOT exclude malignancy (false negative rate 20–40%). ' +
      'If clinical suspicion remains high: repeat tissue acquisition with cholangioscopy or EUS-FNB. ' +
      'Consider steroid trial if IgG4-related cholangiopathy suspected.';
  } else {
    tissueAcquisitionStrategy = `Tissue result: ${input.tissueAcquisitionResult.replace(/_/g, ' ')}. Repeat tissue acquisition with cholangioscopy if clinically indicated.`;
  }

  // ─── Biliary Drainage Strategy ────────────────────────────────────────────
  let biliarDrainageStrategy = '';
  if (input.hasJaundice || input.hasBiliaryStenosis) {
    if (input.strictureLocation === 'distal_cbd') {
      biliarDrainageStrategy =
        'BILIARY DRAINAGE for DISTAL CBD STRICTURE: ' +
        '1) ERCP with SEMS (self-expanding metal stent): preferred for malignant distal stricture. ' +
        '   Covered SEMS (CSEMS): longer patency (6–12 months), removable — preferred for benign or uncertain etiology. ' +
        '   Uncovered SEMS: permanent — use only for confirmed malignant, unresectable disease. ' +
        '2) Plastic stent: bridge to surgery or for benign strictures (exchange every 3 months). ' +
        '3) EUS-CDS (choledochoduodenostomy): if ERCP fails. ' +
        '4) Avoid pre-op stenting if surgery within 2 weeks (increases infection risk).';
    } else if (input.strictureLocation.startsWith('hilar')) {
      biliarDrainageStrategy =
        'BILIARY DRAINAGE for HILAR STRICTURE (Klatskin tumor): ' +
        '1) Unilateral vs bilateral drainage: drain ≥50% of liver volume. ' +
        '   Bismuth I–II: unilateral drainage often sufficient. ' +
        '   Bismuth III–IV: bilateral drainage may be needed. ' +
        '2) ERCP: preferred approach for hilar drainage. ' +
        '3) PTBD: if ERCP not feasible (altered anatomy, failed ERCP). ' +
        '4) Stent type: uncovered SEMS for unresectable malignant hilar stricture (longer patency than plastic). ' +
        '5) Avoid draining undrained segments (cholangitis risk).';
    } else if (input.strictureLocation === 'anastomotic') {
      biliarDrainageStrategy =
        'POST-TRANSPLANT ANASTOMOTIC STRICTURE: ' +
        'ERCP with balloon dilation + multiple plastic stents (side-by-side technique). ' +
        'Stent exchange every 3 months x12 months. ' +
        'Fully covered SEMS (FCSEMS): emerging alternative — better stricture resolution. ' +
        'Surgical revision if endoscopic therapy fails.';
    }
  } else {
    biliarDrainageStrategy = 'No biliary drainage required at this time. Monitor bilirubin and LFTs.';
  }

  // ─── PSC Management ───────────────────────────────────────────────────────
  let pscManagement = 'PSC not identified.';
  if (input.hasPSC) {
    pscManagement =
      'PRIMARY SCLEROSING CHOLANGITIS (PSC) MANAGEMENT (ACG 2023): ' +
      '1) DOMINANT STRICTURE: ERCP with dilation ± short-term plastic stent. ' +
      '   Cholangioscopy + biopsy + FISH to exclude cholangiocarcinoma. ' +
      '   CA 19-9 + IgG4 measurement. ' +
      '2) URSODEOXYCHOLIC ACID (UDCA): ' +
      '   Low-dose UDCA (13–15 mg/kg/day): not recommended by ACG 2023 (no survival benefit). ' +
      '   High-dose UDCA (28–30 mg/kg/day): HARMFUL — increased risk of colorectal cancer. ' +
      '   UDCA NOT recommended for PSC (ACG 2023). ' +
      '3) CRC SURVEILLANCE: annual colonoscopy with chromoendoscopy (PSC + IBD). ' +
      '4) CHOLANGIOCARCINOMA SURVEILLANCE: annual MRCP + CA 19-9. ' +
      '5) LIVER TRANSPLANT: only curative option for PSC. ' +
      '   MELD exception points for PSC-related complications. ' +
      '   5-year post-transplant survival: 85%.';
    if (input.hasDominantStricture) {
      nextSteps.push('ERCP with dilation of dominant stricture', 'Cholangioscopy + biopsy + FISH to exclude cholangiocarcinoma');
    }
  }

  // ─── Resectability and Oncology ───────────────────────────────────────────
  let resectabilityAndOncology = '';
  if (input.tissueAcquisitionResult === 'malignant' || input.imagingFindingsMalignantFeatures) {
    if (input.isResectable && !input.hasDistantMetastases) {
      resectabilityAndOncology =
        'RESECTABLE BILIARY TRACT CANCER (NCCN 2025): ' +
        'Distal cholangiocarcinoma/ampullary: pancreaticoduodenectomy (Whipple). ' +
        'Hilar cholangiocarcinoma (Klatskin): extended hepatectomy ± caudate lobe resection. ' +
        'Intrahepatic CCA: hepatectomy with negative margins. ' +
        'Adjuvant chemotherapy: capecitabine x6 months (BILCAP trial — OS benefit). ' +
        'Surgical oncology referral at high-volume hepatobiliary center.';
      nextSteps.push('Surgical oncology referral at high-volume hepatobiliary center', 'Preoperative biliary drainage if bilirubin >10 mg/dL');
    } else if (input.hasDistantMetastases || !input.isResectable) {
      resectabilityAndOncology =
        'UNRESECTABLE/METASTATIC BILIARY TRACT CANCER (NCCN 2025): ' +
        'First-line: gemcitabine + cisplatin + durvalumab (TOPAZ-1 trial — OS benefit with PD-L1 inhibitor). ' +
        'Alternatively: gemcitabine + cisplatin (ABC-02 trial). ' +
        'FGFR2 fusion (intrahepatic CCA): pemigatinib or infigratinib (FGFR inhibitors). ' +
        'IDH1 mutation: ivosidenib (ClarIDHy trial). ' +
        'MSI-H/dMMR: pembrolizumab. ' +
        'BRAF V600E: dabrafenib + trametinib. ' +
        'Palliative biliary drainage (SEMS) for jaundice.';
      nextSteps.push('Medical oncology referral', 'NGS/molecular profiling of tumor tissue (FGFR2, IDH1, MSI, BRAF)', 'Palliative SEMS for biliary decompression');
    }
  } else {
    resectabilityAndOncology = 'Malignancy not confirmed. Complete diagnostic workup before oncologic planning.';
  }

  // ─── Surveillance Plan ────────────────────────────────────────────────────
  const surveillancePlan =
    input.hasPSC
      ? 'PSC surveillance: annual MRCP + CA 19-9 + annual colonoscopy with chromoendoscopy (if IBD). ' +
        'Cholangioscopy if dominant stricture or rising CA 19-9.'
      : input.tissueAcquisitionResult === 'benign' && malignancyRisk !== 'LOW'
      ? 'Indeterminate stricture: repeat MRCP at 3 months. Repeat tissue acquisition if stricture persists or progresses.'
      : 'Follow-up MRCP at 3–6 months for benign strictures. Annual MRCP for PSC.';

  if (nextSteps.length === 0) {
    nextSteps.push(
      'MRCP for biliary anatomy',
      'CA 19-9, CEA, IgG4 serum markers',
      'ERCP with brush cytology + FISH',
      'Cholangioscopy if ERCP cytology non-diagnostic',
      'Multidisciplinary hepatobiliary tumor board'
    );
  }

  const rationale =
    `Location: ${input.strictureLocation.replace(/_/g, ' ')}. ` +
    `Suspected etiology: ${input.suspectedEtiology.replace(/_/g, ' ')}. ` +
    `Malignancy risk: ${malignancyRisk}. ` +
    `CA 19-9: ${input.ca199 ?? 'not measured'}. ` +
    `IgG4: ${input.igg4 ?? 'not measured'}. ` +
    `Tissue result: ${input.tissueAcquisitionResult.replace(/_/g, ' ')}. ` +
    `PSC: ${input.hasPSC ? 'Yes' : 'No'}.`;

  return {
    primaryRecommendation:
      input.hasFever && input.hasChills && input.hasJaundice
        ? 'ACUTE CHOLANGITIS: urgent ERCP for biliary decompression + IV antibiotics.'
        : input.hasPSC && input.hasDominantStricture
        ? 'PSC with dominant stricture: ERCP dilation + cholangioscopy to exclude cholangiocarcinoma.'
        : input.igg4 !== undefined && input.igg4 > 135
        ? 'IgG4-related sclerosing cholangitis: steroid trial (prednisone 40mg/day) before biliary stenting.'
        : malignancyRisk === 'HIGH'
        ? 'High malignancy risk: cholangioscopy with targeted biopsy + ERCP biliary drainage + multidisciplinary tumor board.'
        : 'Biliary stricture of uncertain etiology: MRCP + ERCP with brush cytology + FISH + cholangioscopy for tissue acquisition.',
    malignancyRiskAssessment,
    diagnosticWorkup,
    tissueAcquisitionStrategy,
    biliarDrainageStrategy,
    pscManagement,
    resectabilityAndOncology,
    surveillancePlan,
    urgentFlags,
    nextSteps,
    evidenceLevel: 'B',
    rationale,
    references: [
      {
        citation: 'ASGE Standards of Practice Committee. The role of endoscopy in the evaluation of suspected choledocholithiasis. Gastrointest Endosc. 2019;89(6):1075-1105.',
        pmid: '30979521',
        url: 'https://pubmed.ncbi.nlm.nih.gov/30979521/',
      },
      {
        citation: 'Morizane C, et al. Gemcitabine, Cisplatin, and Durvalumab for Biliary Tract Cancers (TOPAZ-1). N Engl J Med. 2022;386(19):1807-1818.',
        pmid: '35551092',
        url: 'https://pubmed.ncbi.nlm.nih.gov/35551092/',
      },
      {
        citation: 'Primrose JN, et al. Capecitabine Compared with Observation in Resected Biliary Tract Cancer (BILCAP). Lancet Oncol. 2019;20(5):663-673.',
        pmid: '30922733',
        url: 'https://pubmed.ncbi.nlm.nih.gov/30922733/',
      },
      {
        citation: 'Chapman MH, et al. British Society of Gastroenterology and UK-PSC Guidelines for the Diagnosis and Management of Primary Sclerosing Cholangitis. Gut. 2019;68(8):1356-1378.',
        pmid: '31154395',
        url: 'https://pubmed.ncbi.nlm.nih.gov/31154395/',
      },
      {
        citation: 'Navaneethan U, et al. Cholangioscopy as an Adjunct to ERCP for Tissue Sampling in Indeterminate Biliary Strictures. Gastrointest Endosc. 2024.',
        url: 'https://www.asge.org',
      },
    ],
  };
}
